export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.remembered = new Map()
  }

  advance(key, tick) {
    let ticks = this.remembered.get(key)
    if (!ticks) {
      ticks = []
      this.remembered.set(key, ticks)
    }
    const cutoff = tick - this.span
    let start = 0
    while (start < ticks.length && ticks[start] <= cutoff) start++
    if (start > 0) ticks.splice(0, start)
  }

  allows(key) {
    return BigInt(this.remembered.get(key).length) < this.limit
  }

  record(key, tick) {
    this.remembered.get(key).push(tick)
  }
}
"}

