const UINT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function requireUint(token, field, least, line) {
  if (!UINT_RE.test(token) || BigInt(token) < least) {
    throw new ParseError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(token)
}

