 * @param {string} text the raw limiter file
 * @returns {{ policies: Map<string, object>, routes: { prefix: string, policies: object[] }[], events: { line: number, tick: bigint, key: string }[] }}
 */
export function parseFile(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routePrefixes = new Map()
  const routes = []
  const events = []
  let eventSeen = false
  let lastTick = null

