      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const capacity = requireUint(capacityTok, 'capacity', 1n, lineNo)
      const refill = requireUint(refillTok, 'refill', 0n, lineNo)
      const per = requireUint(perTok, 'per', 1n, lineNo)
      policies.set(name, { name, policy: new TokenBucket(capacity, refill, per) })
    } else if (word === 'window') {
      if (tokens.length !== 4) {
        throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitTok, spanTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const limit = requireUint(limitTok, 'limit', 0n, lineNo)
      const span = requireUint(spanTok, 'span', 1n, lineNo)
      policies.set(name, { name, policy: new SlidingWindow(limit, span) })
    } else if (word === 'route') {
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      const resolved = []
      for (const pname of policyNames) {
        const entry = policies.get(pname)
        if (!entry) throw new ParseError(lineNo, `unknown policy ${pname}`)
        resolved.push(entry)
      }
      if (eventSeen) throw new ParseError(lineNo, 'declarations must come before the first event')
      const route = { prefix, policies: resolved }
      routePrefixes.set(prefix, route)
      routes.push(route)
    } else if (word === 'event') {
