  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    fail('usage: cli.js replay|summary')
    return
  }

  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  const text = chunks.join('')

  let parsed
  try {
    parsed = parseFile(text)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.message)
      return
    }
    throw err
  }

  const { verdicts, summary } = simulate(parsed)

  const out = []
